func (f InvoiceFilter) match(inv Invoice) bool {
	return (f.CustomerID == "" || inv.CustomerID == f.CustomerID) && (f.SubscriptionID == "" || inv.SubscriptionID == f.SubscriptionID) && (f.Status == "" || inv.Status == f.Status)
}

// InvoicePosition is where a page of invoices starts: after the invoice created at CreatedAt with this ID.
type InvoicePosition struct {
	CreatedAt time.Time
	ID        string
}

// before reports whether the invoice comes after the position.
func (p InvoicePosition) before(inv Invoice) bool {
	if !p.CreatedAt.Equal(inv.CreatedAt) {
		return p.CreatedAt.Before(inv.CreatedAt)
	}
	return p.ID < inv.ID
}

// invoiceBefore orders invoices oldest first, ties by ID.
func invoiceBefore(a, b Invoice) bool {
	if !a.CreatedAt.Equal(b.CreatedAt) {
		return a.CreatedAt.Before(b.CreatedAt)
	}
	return a.ID < b.ID
}

// indexInvoice adds a stored invoice to its organization's index. The caller holds the lock.
func (s *Store) indexInvoice(inv Invoice) {
	ids := s.invoiceIDs[inv.OrgID]
	i := sort.Search(len(ids), func(i int) bool { return invoiceBefore(inv, s.invoices[ids[i]]) })
	ids = append(ids, "")
	copy(ids[i+1:], ids[i:])
	ids[i] = inv.ID
	s.invoiceIDs[inv.OrgID] = ids
}

// ListInvoices returns an organization's invoices that match f, oldest first (ties by ID).
func (s *Store) ListInvoices(orgID string, f InvoiceFilter) []Invoice {
	s.mu.Lock()
	out, _ := s.matchingInvoices(s.invoiceIDs[orgID], f, math.MaxInt)
	s.mu.Unlock()
	return cloneInvoices(out)
}

// ListInvoicePage returns one page of an organization's invoices that match f, oldest first (ties by ID): up to limit of
// those after the position (from the first when after is nil). It also reports whether more invoices match after the page.
func (s *Store) ListInvoicePage(orgID string, f InvoiceFilter, after *InvoicePosition, limit int) ([]Invoice, bool) {
	s.mu.Lock()
	ids := s.invoiceIDs[orgID]
	start := 0
	if after != nil {
		start = sort.Search(len(ids), func(i int) bool { return after.before(s.invoices[ids[i]]) })
	}
	out, more := s.matchingInvoices(ids[start:], f, limit)
	s.mu.Unlock()
	return cloneInvoices(out), more
}

// matchingInvoices copies the invoices with these IDs that match f, up to limit of them, and reports whether more match.
// The caller holds the lock.
func (s *Store) matchingInvoices(ids []string, f InvoiceFilter, limit int) ([]Invoice, bool) {
	out := []Invoice{}
	for _, id := range ids {
		inv := s.invoices[id]
		if !f.match(inv) {
			continue
		}
		if len(out) == limit {
			return out, true
		}
		out = append(out, copyInvoice(inv))
	}
	return out, false
}

// cloneInvoices replaces each invoice with a deep copy through JSON, as ListInvoices always has.
func cloneInvoices(invs []Invoice) []Invoice {
	for i := range invs {
		invs[i] = cloneInvoice(invs[i])
	}
	return invs
}

