308	func (f InvoiceFilter) match(inv Invoice) bool {
309		return (f.CustomerID == "" || inv.CustomerID == f.CustomerID) && (f.SubscriptionID == "" || inv.SubscriptionID == f.SubscriptionID) && (f.Status == "" || inv.Status == f.Status)
